  const r = run(survey(), [{ op: "create_behavior", label: "hint", target: "Q3", on: "select_option", options: ["2"], effects: [{ do: "popup", text: "Tell us why", placement: "tooltip", dismiss: "close", target: "Q3.option:2" }] }]);
